def transform(grid):
    result = [row[:] for row in grid]
    height, width = len(result), len(result[0])
    background = Counter(cell for row in result for cell in row).most_common(1)[0][0]
    seen = set()

    for row in range(height):
        for col in range(width):
            color = result[row][col]
            if color == background or (row, col) in seen:
                continue

            queue = deque([(row, col)])
            seen.add((row, col))
            component = []
            while queue:
                y, x = queue.popleft()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < height and 0 <= xx < width and
                            (yy, xx) not in seen and result[yy][xx] == color):
                        seen.add((yy, xx))
                        queue.append((yy, xx))

            top = min(y for y, _ in component)
            bottom = max(y for y, _ in component)
            left = min(x for _, x in component)
            right = max(x for _, x in component)
            if bottom - top < 2 or right - left < 2:
                continue

            border = {
                (y, x)
                for y in range(top, bottom + 1)
                for x in range(left, right + 1)
                if y in (top, bottom) or x in (left, right)
            }
            if set(component) != border:
                continue

            interior = [
                (y, x)
                for y in range(top + 1, bottom)
                for x in range(left + 1, right)
            ]
            if not interior or any(result[y][x] != background for y, x in interior):
                continue

            fill = 7 if len(interior) % 2 else 2
            for y, x in interior:
                result[y][x] = fill

    return result
